function drawSprite(f,t,alpha=1,height=93){if(f.id>=8){if(typeof drawTrioSprite==='function')drawTrioSprite(f,t,alpha,height);return;}if(typeof motionReady==='function'&&motionReady()){drawMotionFighter(f,t,alpha,height);return;}if(f.id>=5){if(typeof drawGuestSprite==='function')drawGuestSprite(f,t,alpha,height);return;}if(!atlas.complete||!atlas.naturalWidth)return;let row=f.attack>0?4:!f.preview&&f.y<421?3:f.dash>0?1:f.moving?1+Math.floor(f.walk/2)%2:0;const walking=f.moving&&!f.preview&&f.y===424&&f.attack<=0&&f.dash<=0&&walkArt.complete&&walkArt.naturalWidth;const frame=walking?walkFrames[Math.floor(f.walk/(Math.PI*2)*5)%5][f.id]:frames[row][f.id],scale=height/230,w=frame[2]*scale,h=frame[3]*scale;const anchors=[.65,.57,.60,.62,.51];c.save();c.globalAlpha=alpha;if(alpha===1&&height<110){c.fillStyle='#02071588';c.beginPath();c.ellipse(f.x,428,26,6,0,0,7);c.fill()}c.translate(Math.round(f.x),Math.round(f.y));c.scale(f.face,f.preview?1:renderRatio);if(!f.preview&&f.hitReact>0){const recoil=Math.sin(Math.min(1,f.hitReact/.28)*Math.PI);c.rotate(f.hitDir*f.face*recoil*.18);c.translate(-f.hitDir*f.face*recoil*5,0);c.scale(1+.1*recoil,1-.08*recoil);if(f.hitReact>.19)c.filter='brightness(2.2) saturate(.35)';}let bob=row===0?Math.sin(t*3.8+f.id)*1.4:row===1||row===2?-Math.abs(Math.sin(f.walk))*2:0;if(f.land>0)c.scale(1.07,.92);if(f.dash>0)c.transform(1,0,-.24,1,0,0);if(f.inv>0&&Math.floor(t*25)%2&&alpha===1)c.globalAlpha=.65;if(walking)drawWalkingLayers(walkArt,frame,-w*anchors[f.id],-h,w,h,f.walk,f.id,f.moveDir*f.face);else if(activeMelee(f))drawCombatPose(f,height);else c.drawImage(atlas,...frame,-w*anchors[f.id],-h+bob,w,h);c.restore();if(height<110&&alpha===1&&(f.shield>0||f.guard||f.armor>0)){c.save();c.globalAlpha=.5+Math.sin(t*9)*.15;c.strokeStyle=f.armor>0?'#eac66c':'#9eeaff';c.lineWidth=f.armor>0?4:2;c.beginPath();c.ellipse(f.x,f.y-40,38,48,0,0,7);c.stroke();c.restore()}if(height<110&&f.slow>0)text('❄',f.x,f.y+7,18,'#bceaff','center')}
function background(t){const chosen=window.mapImages?.[window.currentMap||0]||arenaArt;if(!chosen.complete||!chosen.naturalWidth){blockBackground(t);return}c.drawImage(chosen,0,0,960,540);const shade=c.createLinearGradient(0,0,0,220);shade.addColorStop(0,'#050918dd');shade.addColorStop(1,'#07132200');c.fillStyle=shade;c.fillRect(0,0,960,220);for(let i=0;i<18;i++){const x=(i*137+t*(9+i%5))%990,y=140+(i*71+t*14)%340;c.save();c.globalAlpha=.35+Math.sin(t+i)*.15;rect(x,y,3,2,i%2?'#e58dd2':'#bde9ff');c.restore()}}
function locomote(f,dir,speed,dt){if(!dir||activeMelee(f)||f.attack>0||f.stun>0||f.dash>0)return;f.skillAnim=null;f.pendingSkill=-1;f.pendingTime=0;fx=fx.filter(e=>e.type!=='comboArc'||e.fighterIndex!==fighters.indexOf(f));if(f.y===424&&f.id>=5){speed*=.83;if(dir!==f.face)speed*=.72;}const before=f.x;if(f.formTime>0&&f.formTier===2)speed*=1.12;f.x=Math.max(35,Math.min(925,f.x+dir*speed*dt));const distance=Math.abs(f.x-before);if((!f.wasMoving&&!f.moving)||f.moveDir!==dir)f.walk=0;f.moving=distance>.01;f.moveDir=dir;if(f.y===424&&distance>0){const oldStep=Math.floor(f.walk/Math.PI);f.walk+=distance/(f.id>=5?[96,100,92,78,78,84][f.id-5]:122)*Math.PI*2;if(Math.floor(f.walk/Math.PI)!==oldStep){if(f===fighters[0])sound(75,.035,'triangle')}}}
