function drawWalkingLayers(img,frame,x,y,w,h,phase,id,dir){
 // Whole authored frames: never rotate or split limbs from the body.
 const index=Math.floor(phase/(Math.PI*2)*5)%5,anchor=walkAnchors[index][id],scale=h/frame[3];
 c.drawImage(img,...frame,-anchor[0]*scale,-anchor[1]*scale,w,h);
}
function spectacle(type,x,y,id,duration=.6,size=100,extra={}){if(spectacles.length>65)spectacles.splice(0,10);spectacles.push({type,x,y,id,age:0,duration,size,seed:Math.random()*30,...extra})}
function updateSpectacles(dt){for(const e of spectacles)e.age+=dt;spectacles=spectacles.filter(e=>e.age<e.duration);if(cinema){cinema.age+=dt;if(cinema.age>cinema.duration)cinema=null}}
function powerSound(id,index){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;for(let layer=0;layer<3;layer++){const o=audio.createOscillator(),g=audio.createGain();o.type=layer===2?'triangle':id===1?'sawtooth':'sine';const f=[180,105,450,130,65,110,80,155,180,150,320][id]*(layer+1)*(index===2?.7:1.5);o.frequency.setValueAtTime(f,now+layer*.025);o.frequency.exponentialRampToValueAtTime(Math.max(25,f*.14),now+.35+index*.12);g.gain.setValueAtTime(.018/(layer+1),now);g.gain.exponentialRampToValueAtTime(.001,now+.4+index*.15);o.connect(g);g.connect(audio.destination);o.start(now+layer*.025);o.stop(now+.5+index*.15)}}catch(e){}}
function stampPower(id,index,x,y,w,h=w,alpha=1,rotation=0,flip=1){if(id>=8){drawTrioEnergy(id,x,y,w,h,powerEventAge??time,alpha,flip);return true;}if(id>=5){stampGuestPower(id,x,y,w,h,powerEventAge??time,alpha,rotation,flip,true);return true;}if(!powerAtlas.complete||!powerAtlas.naturalWidth)return false;const sw=powerAtlas.naturalWidth/5,sh=powerAtlas.naturalHeight/3;c.save();c.translate(x,y);c.rotate(rotation);c.scale(flip,1);c.globalAlpha*=Math.max(0,alpha);drawAnimatedTexture(powerAtlas,id*sw,index*sh,sw,sh,w,h,id,index,false,time);c.restore();return true}
function glow(x,y,r,col,alpha=.5){c.save();c.globalCompositeOperation='screen';c.globalAlpha*=alpha*vfxIntensity;const g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,col);g.addColorStop(.4,col+'80');g.addColorStop(1,col+'00');c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2);c.restore()}
function lightning(x1,y1,x2,y2,col,seed,width=3){c.save();c.lineJoin='miter';const pts=[];for(let i=0;i<=12;i++){const u=i/12,j=i===0||i===12?0:Math.sin(i*4.8+seed)*13;pts.push([x1+(x2-x1)*u+j,y1+(y2-y1)*u+j*.4])}for(const [w,color,alpha] of [[width*5,col,.15],[width*2,col,.55],[width,'#eaffff',1]]){c.strokeStyle=color;c.globalAlpha=alpha*vfxIntensity;c.lineWidth=w;c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke()}c.restore()}
function shockRing(x,y,r,col,alpha=1,flatten=.35){c.save();c.globalAlpha*=alpha;c.strokeStyle=col;c.lineWidth=3;c.beginPath();c.ellipse(x,y,r,r*flatten,0,0,Math.PI*2);c.stroke();c.lineWidth=1;c.globalAlpha*=.5;c.beginPath();c.ellipse(x,y,r+7,r*flatten+3,0,0,Math.PI*2);c.stroke();c.restore()}
function sigil(x,y,r,col,t,alpha=.6){c.save();c.translate(x,y);c.scale(1,.32);c.rotate(t);c.globalAlpha=alpha*vfxIntensity;c.strokeStyle=col;c.lineWidth=2;c.beginPath();c.arc(0,0,r,0,7);c.stroke();c.beginPath();for(let i=0;i<6;i++){let a=i*Math.PI/3;c.lineTo(Math.cos(a)*r*.8,Math.sin(a)*r*.8)}c.closePath();c.stroke();for(let i=0;i<12;i++){c.save();c.rotate(i*Math.PI/6);rect(r-4,-2,12,3,col);c.restore()}c.restore()}
function drawSpectacles(t){for(const e of spectacles){const k=e.age/e.duration,fade=Math.sin(Math.PI*Math.min(1,k)),col=roster[e.id].color;c.save();if(e.type==='charge'){sigil(e.x,e.y+38,44+Math.sin(k*Math.PI)*14,col,t*2,1-k);glow(e.x,e.y,e.size*(.5+k),col,.4*(1-k));for(let i=0;i<8;i++){const a=i*.785+t*5,r=60*(1-k);rect(e.x+Math.cos(a)*r,e.y+Math.sin(a)*r,3,3,col)}}else if(e.type==='explosion'||e.type==='guardHit'){const r=e.size*(.35+k*1.5);glow(e.x,e.y,r,col,.5*(1-k));shockRing(e.x,e.y,r,col,1-k,.8);stampPower(e.id,e.type==='guardHit'?1:e.id===1?1:e.id===4?0:2,e.x,e.y,r*2,r*2,(1-k)*.8,k*.3);for(let i=0;i<14*vfxIntensity;i++){const a=i*2.399+e.seed,rad=r*(.4+k);c.strokeStyle=i%3?'#fff3c9':col;c.lineWidth=i%2?2:4;c.globalAlpha=1-k;c.beginPath();c.moveTo(e.x+Math.cos(a)*rad*.6,e.y+Math.sin(a)*rad*.6);c.lineTo(e.x+Math.cos(a)*rad,e.y+Math.sin(a)*rad);c.stroke()}}else if(e.type==='portal'){stampPower(3,0,e.x,e.y,e.size*fade*.8,e.size*1.4,fade,k*2);glow(e.x,e.y,70,col,.3*fade);shockRing(e.x,e.y+42,50*fade,col,fade)}else if(e.type==='rush'){stampPower(0,1,e.x+e.dir*k*90,e.y,e.size*(.7+k),100,1-k,0,e.dir);lightning(e.x-e.dir*40,e.y,e.x+e.dir*140,e.y,col,t*20,2)}else if(e.type==='shield'||e.type==='armor'){stampPower(e.id,1,e.x,e.y,e.size*(.5+k),e.size*(.5+k),1-k);shockRing(e.x,e.y+40,e.size*k,col,1-k)}c.restore();}}
function drawShot(s,t){if(s.launchDelay>0)return;drawAnimatedProjectile(s,t)}
function drawFX(e,t){if(e.type?.startsWith('trio')){drawTrioEffect(e,t);return;}if(e.type?.startsWith('guest')){drawGuestEffect(e,t);return;}drawPowerMotion(e,t);if(e.type==='comboArc'){drawComboArc(e,t);return;}if(e.type==='number'){legacyFX(e,t);return}const k=Math.max(0,1-e.life/e.total),fade=Math.sin(Math.min(1,k)*Math.PI),col=e.col,id=e.owner?e.owner.id:0;if(e.wait>0){if(e.owner){sigil(e.x,423,e.radius,col,t*3,.5);glow(e.x,412,45,col,.18);c.save();c.globalAlpha=.25;c.strokeStyle=col;c.setLineDash([3,7]);c.beginPath();c.moveTo(e.x,180);c.lineTo(e.x,420);c.stroke();c.restore()}return}c.save();if(e.type==='ring'){sigil(e.x,e.y,25+k*40,col,t*3,1-k)}else if(e.type==='slash'){c.translate(e.x,e.y);c.rotate(-.7);c.strokeStyle='#f6fff2';c.lineWidth=4;c.globalAlpha=1-k;c.beginPath();c.arc(0,0,18+k*20,-1.2,1.2);c.stroke();stampPower(0,1,0,0,75,65,(1-k)*.5)}else if(e.type==='storm'){glow(e.x,365,100,col,.5*fade);for(let j=0;j<3;j++)lightning(e.x+(j-1)*25,140,e.x,416,col,t*24+j,3);stampPower(0,2,e.x,355,180*(.7+k),230,fade);shockRing(e.x,424,95*k,col,1-k);sigil(e.x,424,60,col,t*4,fade)}else if(e.type==='eruption'){glow(e.x,355,150,'#ff964d',.6*fade);stampPower(1,1,e.x,425-100*fade,210*(.6+k*.5),270*fade,Math.min(1,fade*2));shockRing(e.x,424,120*k,'#ffc068',1-k);for(let j=0;j<12;j++){const a=j*2.4,r=k*110;rect(e.x+Math.cos(a)*r,415-Math.sin(k*Math.PI)*(30+j*6)+k*k*40,5,8,j%2?'#ff9b44':'#ffe8a4')}}else if(e.type==='eclipse'){c.save();c.globalAlpha=.22*fade;rect(0,120,960,330,'#150b35');c.restore();glow(e.x,365,155,col,.4*fade);stampPower(3,2,e.x,365,260*(.7+k*.5),245*(.7+k*.5),fade,k*.7);for(let j=0;j<5;j++){const a=t*5+j*1.257;lightning(e.x+Math.cos(a)*100,e.y-60+Math.sin(a)*75,e.x,365,col,t*9+j,1.4)}shockRing(e.x,424,140*fade,col,fade)}else if(e.type==='blizzard'){const cx=e.x,cy=380;glow(cx,cy,85,'#82d6ff',.3*fade);stampPower(2,2,cx,cy,130,145,fade*.8,k*.3);for(let j=0;j<7;j++){const a=t*4+j*.9;rect(cx+Math.cos(a)*65,cy+Math.sin(a)*45,3,5,'#e4faff')}sigil(cx,424,55,col,-t*3,fade)}else if(e.type==='impact'){stampPower(4,0,e.x,395,180*(.65+k),150,1-k);glow(e.x,390,100,col,.6*(1-k));shockRing(e.x,424,110*k,col,1-k)}else if(e.type==='quake'){for(let j=-3;j<=3;j++){const x=e.x+j*k*140,scale=Math.sin(k*Math.PI);stampPower(4,2,x,424-45*scale,155,170*scale,Math.min(1,fade*2));if(j%2===0)lightning(x-40,424,x+40,424,'#f2d677',t*3+j,2)}shockRing(e.x,424,k*600,col,1-k,.16)}else if(e.type==='guestMuzzle'||e.type==='knightSlash')drawModeEffect(e,t);else legacyFX(e,t);c.restore()}
function drawAuras(t){for(const f of fighters){if(f.id>=8){if(f.shield>0){c.save();c.translate(f.x,f.y-39);c.scale(1,renderRatio);c.strokeStyle=f.r.color;c.lineWidth=2;c.globalAlpha=.55;c.beginPath();for(let n=0;n<6;n++){const a=Math.PI/3*n-Math.PI/2,x=Math.cos(a)*36,y=Math.sin(a)*46;n?c.lineTo(x,y):c.moveTo(x,y);}c.closePath();c.stroke();c.restore();}continue;}if(f.shield>0){const col='#9bdcff';glow(f.x,f.y-38,75,col,.18);stampPower(2,1,f.x,f.y-41,120,130,.4+Math.sin(t*4)*.08);sigil(f.x,426,45,col,t,.5)}if(f.armor>0){stampPower(4,1,f.x,f.y-40,130,130,.55);for(let i=0;i<4;i++){const a=t*1.5+i*1.57,x=f.x+Math.cos(a)*38,y=f.y-38+Math.sin(a)*30;rect(x,y,7,9,'#e8c774');rect(x+2,y+2,3,4,'#a7ed70')}}}}
function drawCinema(){if(!cinema)return;const k=cinema.age/cinema.duration,a=Math.min(1,k*6,(1-k)*6),r=roster[cinema.id];c.save();c.globalAlpha=a;c.translate(0,145);const g=c.createLinearGradient(0,0,960,0);g.addColorStop(0,r.color+'cc');g.addColorStop(.6,'#091228f0');g.addColorStop(1,'#09122800');c.fillStyle=g;c.fillRect(0,0,760,65);rect(0,0,640,2,r.color);rect(0,63,640,2,r.color);text('HABILIDADE / '+r.name,35,19,10,'#f0ffff');text(cinema.name,35,49,28,'#fff');stampPower(cinema.id,2,590,30,110,85,.8);c.restore()}
