function updatePowerGallery(id){const r=roster[id],gallery=$('powerPreviews');if(!gallery)return;gallery.innerHTML=r.skills.map((s,i)=>`<div class="power-card" style="--power:${r.color}"><div class="power-art" style="background-position:${id*25}% ${i*50}%"></div><div class="power-card-title"><kbd>${['Z','X','C'][i]}</kbd><b>${s[1]}</b></div></div>`).join('');$('vfxCaption').textContent=r.name+' / '+['Arcos elétricos, corte de energia e tempestade de relâmpagos.','Fogo vivo, erupção de lava e a ascensão da Fênix.','Cristais afiados, barreira facetada e explosão glacial.','Portais sombrios, veneno espectral e um eclipse de energia.','Impactos de rocha, armadura rúnica e terremotos devastadores.','M1 com balas, rajadas carmesins e Eclipse de Sangue: Frenesi Oni.','Cortes de antimagia, contra-ataque e transformação demoníaca com voo.','Adagas, troca de sombras e cavaleiros com vida e ataques próprios.','Picanhas giratórias, laço de espeto e Churrasco Cósmico.','Rajada do Zap, Arrancada do Cercadinho e Chuva de Figurinhas.','Getsuga Tenshō, Shunpo, Bankai e máscara Hollow.'][id]}

let artReady=false;
const mobileReview=new URLSearchParams(location.search).get('view')==='mobile';
function isMobileLayout(){return mobileReview||window.matchMedia('(pointer:coarse)').matches||window.innerWidth<=600||(window.innerWidth<1100&&window.innerHeight<600)}
function fitMobile(){const vv=window.visualViewport;const visibleH=mobileReview?420:Math.min(window.innerHeight,vv?vv.height:window.innerHeight);const visibleW=mobileReview?900:Math.min(window.innerWidth,vv?vv.width:window.innerWidth);document.documentElement.style.setProperty('--visible-height',Math.floor(visibleH)+'px');document.documentElement.style.setProperty('--visible-width',Math.floor(visibleW)+'px');document.documentElement.style.setProperty('--viewport-top',(vv?vv.offsetTop:0)+'px');document.body.classList.toggle('mobile-device',isMobileLayout());document.body.classList.toggle('mobile-review',mobileReview);const portrait=window.innerHeight>window.innerWidth&&!mobileReview;document.body.classList.toggle('portrait-device',portrait);if(portrait&&mode==='fight')pause()}
async function activateLandscape(force=false){if(!isMobileLayout()&&!force)return;try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen()}catch(e){}try{if(screen.orientation&&screen.orientation.lock)await screen.orientation.lock('landscape')}catch(e){}fitMobile()}
window.addEventListener('resize',fitMobile);if(window.visualViewport){window.visualViewport.addEventListener('resize',fitMobile);window.visualViewport.addEventListener('scroll',fitMobile)}window.addEventListener('orientationchange',()=>{fitMobile();requestAnimationFrame(fitMobile)});document.addEventListener('fullscreenchange',fitMobile);$('rotateFullscreen').onclick=()=>activateLandscape(true);$('retryLoad').onclick=()=>location.reload();fitMobile();
const trioBody29=[8,9,10].map(id=>{const img=new Image();img.src='assets/trio-'+id+'-v29.png';return img;});
const trioFormWalk29=new Image();trioFormWalk29.src='assets/trio-form-walk-v29.png';
const trioVfx29=new Image();trioVfx29.src='assets/trio-vfx-v29.png';
async function prepareArtwork(){const art=[atlas,walkArt,arenaArt,powerAtlas,combatArt,specialArt,powerFrames,fighterFramesArt,guestArt,guestPowerArt,meleeArtA,meleeArtB,motionArtA,motionArtB,formsArt,airArt,signatureArt,gaitArt,formGaitArt,trioWalkArt,trioCombatArt,...trioBody29,trioVfx29,trioFormWalk29];let count=0;const names=['personagens','animações','cenário','poderes','combos','especiais','quadros de efeitos','quadros de luta','novos lutadores','novos poderes','combos detalhados I','combos detalhados II','movimentos limpos I','movimentos limpos II','formas e cavaleiros','voo e habilidades','assinaturas de combate','caminhada em oito quadros','passos das transformações','novos caminhantes','novos combos','Lula animado','Bolsonaro animado','Ichigo e transformações','efeitos animados','passos Bankai e Hollow'];$('play').disabled=true;try{await Promise.all(art.map(async(img,i)=>{if(img.decode)await img.decode();else await new Promise((resolve,reject)=>{if(img.complete&&img.naturalWidth){resolve();return}img.onload=resolve;img.onerror=reject});if(!img.naturalWidth)throw new Error(names[i]);count++;$('loadProgress').style.width=count/art.length*100+'%';$('loadStatus').textContent=count+' / '+art.length+' · '+names[i]+' prontos';}));artReady=true;$('play').disabled=false;$('bootScreen').classList.add('hidden');}catch(e){$('bootTitle').textContent='Não foi possível carregar toda a arte.';$('loadStatus').textContent='Confira a conexão e toque em tentar novamente.';$('retryLoad').classList.remove('hidden')}}prepareArtwork();

function requestSkill(f,index){if(mode!=='fight'||specialScene)return false;if(!window.net?.active||net.role!=='guest')trySignatureCancel(f,index);if(window.net?.active&&net.role==='guest'){net.actions.push(index);return true;}if(cast(f,index))return true;const skill=f.r.skills[index];if(f.cd[index]===0&&f.en>=skill[4]){f.pendingSkill=index;f.pendingTime=.5}return false}

window.paintRiftSprites=function(t){const saved=c;document.querySelectorAll('.rf-sprite').forEach(cv=>{if(cv.offsetParent===null)return;c=cv.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,cv.width,cv.height);const id=cv.dataset.selected==='true'?selected:Math.max(0,Math.min(roster.length-1,Number(cv.dataset.charId)||0));const f=makeFighter(id,cv.width*.54);f.y=cv.height*.88;f.preview=true;f.face=1;drawSprite(f,t,1,cv.height*.7);});c=saved};

