function releaseBattle(){battleIntro=null;clearInput();if(window.net)net.actions=[];mode='fight';aiTimer=.65;banner='FIGHT!';bannerTime=.45;sound(620,.16,'triangle')}
function drawBattleIntro(){const active=mode==='intro'&&battleIntro;$('skipIntro').classList.toggle('hidden',!active||!!window.net?.active);if(!active)return;const a=battleIntro.age;rect(0,0,960,46,'#030713');rect(0,430,960,110,'#030713');text('RIFT FIGHTERS / DUELO DOS ELEMENTOS',480,28,13,'#7ccfff','center');if(battleIntro.full&&a<4.6){const i=a<2.3?0:1,f=fighters[i],line=introLines[f.id][i],n=Math.floor((a%2.3)*35);text(f.r.name,480,462,23,f.r.color,'center');text(line.slice(0,n),480,499,18,'#f1f5ff','center');}else{const t=a-(battleIntro.full?4.6:0);text(t<.75?'ROUND '+round:'FIGHT!',480,265,t<.75?42:72,t<.75?'#ffffff':'#b9ff65','center')}}
$('skipIntro').onclick=()=>{if(mode==='intro'&&!window.net?.active)releaseBattle()};
